  ?uri np:tieneIdiomaOriginal np:idioma_frances . 
  ?uri a np:Novela 
}

PREFIX np: <http://novelas-populares.org/>
SELECT DISTINCT ?uri WHERE { 
  ?uri np:publicadaPor np:editorial_editorial_sopena . 
  ?uri np:tieneIdiomaOriginal np:idioma_ingles . 
  ?uri a np:Novela 
}

PREFIX np: <http://novelas-populares.org/>
SELECT DISTINCT ?uri WHERE { 
  ?uri np:tieneAutor ?a . 
  ?a np:paisDeNacimiento np:pais_noruega . 
  ?uri a np:Novela 
}
